StringView WebKitHTMLEntityTableEntry::nameCharacters() const
{
    return staticEntityStringStorage.substring_view(nameCharactersOffset);
}

Span<const WebKitHTMLEntityTableEntry> WebKitHTMLEntityTable::entriesStartingWith(u16 c)
{
    if (c >= 'A' && c <= 'Z') {
        const size_t first = uppercaseOffset[c - 'A'];
        const size_t last = uppercaseOffset[c - 'A' + 1];
        return Span<const WebKitHTMLEntityTableEntry>(staticEntityTable).slice(first, last - first);

        // auto* start = &staticEntityTable[uppercaseOffset[c - 'A']];
        // return unsafeMakeSpan(start, &staticEntityTable[uppercaseOffset[c - 'A' + 1] - 1] - start + 1);
    }
    if (c >= 'a' && c <= 'z') {
        const size_t first = lowercaseOffset[c - 'a'];
        const size_t last = lowercaseOffset[c - 'a' + 1];
        return Span<const WebKitHTMLEntityTableEntry>(staticEntityTable).slice(first, last - first);

        // auto* start = &staticEntityTable[lowercaseOffset[c - 'a']];
        // return unsafeMakeSpan(start, &staticEntityTable[lowercaseOffset[c - 'a' + 1] - 1] - start + 1);
    }
    return { };
}

Span<const WebKitHTMLEntityTableEntry> WebKitHTMLEntityTable::entries()
{
    return staticEntityTable;
}

